const assistantThreadsList = `-- name: AssistantThreadsList :many
SELECT id, uuid, organization_id, user_id, title, context, escalated_at, ticket_ref, created_at, updated_at FROM assistant_threads
WHERE organization_id = $1 AND user_id = $2
ORDER BY updated_at DESC
LIMIT 50
`

type AssistantThreadsListParams struct {
	OrganizationID int64 `json:"organization_id"`
	UserID         int64 `json:"user_id"`
}

func (q *Queries) AssistantThreadsList(ctx context.Context, arg AssistantThreadsListParams) ([]AssistantThread, error) {
	rows, err := q.db.Query(ctx, assistantThreadsList, arg.OrganizationID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AssistantThread{}
	for rows.Next() {
		var i AssistantThread
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.UserID,
			&i.Title,
			&i.Context,
			&i.EscalatedAt,
			&i.TicketRef,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

