const assistantUsageSummary = `-- name: AssistantUsageSummary :one
SELECT COUNT(*)::bigint AS calls,
       COUNT(DISTINCT organization_id)::bigint AS organizations,
       COALESCE(SUM(input_tokens), 0)::bigint AS input_tokens,
       COALESCE(SUM(output_tokens), 0)::bigint AS output_tokens,
       COALESCE(SUM(cost_micros), 0)::bigint AS cost_micros
FROM assistant_usage WHERE created_at >= $1
`

type AssistantUsageSummaryRow struct {
	Calls         int64 `json:"calls"`
	Organizations int64 `json:"organizations"`
	InputTokens   int64 `json:"input_tokens"`
	OutputTokens  int64 `json:"output_tokens"`
	CostMicros    int64 `json:"cost_micros"`
}

func (q *Queries) AssistantUsageSummary(ctx context.Context, since pgtype.Timestamptz) (AssistantUsageSummaryRow, error) {
	row := q.db.QueryRow(ctx, assistantUsageSummary, since)
	var i AssistantUsageSummaryRow
	err := row.Scan(
		&i.Calls,
		&i.Organizations,
		&i.InputTokens,
		&i.OutputTokens,
		&i.CostMicros,
	)
	return i, err
}

const assistantUsageToday = `-- name: AssistantUsageToday :one
SELECT COUNT(*)::bigint FROM assistant_usage
WHERE organization_id = $1 AND kind = 'chat' AND created_at >= date_trunc('day', NOW() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
`

// Calls since the start of the current UTC day (the per-organization limit).
func (q *Queries) AssistantUsageToday(ctx context.Context, organizationID pgtype.Int8) (int64, error) {
	row := q.db.QueryRow(ctx, assistantUsageToday, organizationID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
